"use client";

import Navbar from "../components/layout/navbar";
import SideBar from "@components/layout/sidebar";
import { ReactLenis } from "@utils/react-lenis";
import PathChecker from "@lib/page-path-checker";
import TextArea from "@components/functional-comps/textareaa";
import { useState } from "react";
import "@styles/theme/main.global.css";
import "boxicons/css/boxicons.min.css";
import { useTheme } from "@providers/ThemeProvider";
import SideBarSmall from "@components/layout/sidebar_small";

export default function Home() {
  const { theme } = useTheme();
  const darkTheme = theme === "dark";

  const [expanded, setExpanded] = useState(false);

  return (
    <ReactLenis
      root
      options={{
        lerp: 0.1,
        touchMultiplier: 1.25,
      }}
    >
      <main
        className={`${
          darkTheme
            ? "bg-dark-black-primary text-dark-white-primary"
            : "bg-light-white-primary text-light-black-primary"
        }`}
      >
        <PathChecker />
        <section className="flex h-[100vh] w-[100%]">
          {/* Sidebar */}
          <aside
            className={`max-w-[260px] ${
              expanded ? "w-[100%]" : "w-[60px]"
            } h-[100vh] z-50 transition-all duration-1000 ease-in-out max-[910px]:absolute max-[910px]:max-w-[unset] max-[910px]:w-[100%] bg-dark-shade-1`}
          >
            <div
              className={`max-w-[390px] ${
                expanded ? "w-[100%]" : "w-[60px]"
              } h-[100vh] transition-all duration-1000 ease-in-out overflow-hidden`}
            >
              <SideBar />
            </div>
            <div>
              <SideSarSmall/>
            </div>
          </aside>

          {/* Main content */}
          <section className="flex flex-col h-[100%] w-full">
            <nav className="z-[100] flex justify-center w-[100%] h-[80px]">
              <Navbar />
            </nav>

            {/* Home page content */}
            <main
              className={`home-page ${
                darkTheme
                  ? "bg-dark-black-primary text-dark-white-primary"
                  : "bg-light-white-primary text-light-black-primary"
              } h-[100%] w-[100%]`}
            >
              <div className="h-full flex flex-col w-[100%]">
                <div className="h-[50%] w-[100%] flex flex-col justify-end items-center gap-3">
                  <div className="min-w-[300px] max-w-[600px] w-[100%] px-4 text-center font-bold font-sans text-[24px]">
                    Introducing with WoahAI-2
                  </div>
                  <div
                    className={`min-w-[300px] max-w-[600px] w-[100%] px-4 text-center pb-2.5 text-[14px] ${
                      darkTheme
                        ? "text-dark-white-secondary"
                        : "text-light-black-secondary"
                    }`}
                  >
                    WoahGPT now has our smartest, fastest, most useful model
                    yet, with thinking built in — so you get the best answer,
                    every time.
                  </div>
                </div>
                <div className="h-[50%] w-[100%] flex flex-col justify-start items-center">
                  <div className="min-w-[300px] max-w-[690px] w-[100%] px-4">
                    <TextArea />
                  </div>
                </div>
              </div>
            </main>
          </section>
        </section>
      </main>
    </ReactLenis>
  );
}
